---DISCOVERY---
package openai

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/modelmatch"
	"github.com/DocumentDrivenDX/fizeau/internal/sdk/openaicompat"
)

// ScoredModel is a discovered model with a selection preference score.
// Higher scores are preferred by the auto-selection logic.
type ScoredModel struct {
	// ID is the model identifier returned by the server's /v1/models endpoint.
	ID string
	// CatalogRef is the catalog target ID if this model is recognized in the
	// model catalog for the provider's surface. Empty for unrecognized models.
	CatalogRef string
	// PatternMatch is true when this model matched the configured model_pattern.
	PatternMatch bool
	// Score summarises the selection preference: 3 = catalog-recognized,
	// 2 = pattern-matched, 1 = uncategorized.
	Score int
}

// DiscoverModels queries the generic /v1/models endpoint through the shared
// OpenAI-compatible SDK. It is kept here as a package-level compatibility
// wrapper for existing provider tests and callers inside this package.
func DiscoverModels(ctx context.Context, baseURL, apiKey string) ([]string, error) {
	return openaicompat.DiscoverModels(ctx, baseURL, apiKey)
}

// RankModels scores and sorts a list of discovered model IDs by selection
// preference:
//
//   - Score 3 — catalog-recognized: the model ID appears in knownModels (a map
//     from concrete model ID to catalog target ID, e.g. from
//     Catalog.AllConcreteModels). These are explicitly tracked models; prefer
//     them when auto-selecting.
//   - Score 2 — pattern-matched: the model ID matches the case-insensitive
//     pattern regex (pattern == "" means this tier is skipped).
//   - Score 1 — uncategorized: known to the server but not in the catalog or
//     pattern.
//
// Within each score tier, the original server-returned order is preserved.
// Returns an error only if pattern is non-empty and fails to compile.
func RankModels(candidates []string, knownModels map[string]string, pattern string) ([]ScoredModel, error) {
	var patternRe *regexp.Regexp
	if pattern != "" {
		re, err := regexp.Compile("(?i)" + pattern)
		if err != nil {
			return nil, fmt.Errorf("discovery: invalid model_pattern %q: %w", pattern, err)
		}
		patternRe = re
	}

	scored := make([]ScoredModel, 0, len(candidates))
	for _, id := range candidates {
		sm := ScoredModel{ID: id, Score: 1}
		if ref, ok := knownModels[id]; ok {
			sm.CatalogRef = ref
			sm.Score = 3
		} else if patternRe != nil && patternRe.MatchString(id) {
			sm.PatternMatch = true
			sm.Score = 2
		}
		scored = append(scored, sm)
	}

	// Stable sort: higher score first, original order preserved within tier.
	sort.SliceStable(scored, func(i, j int) bool {
		return scored[i].Score > scored[j].Score
	})
	return scored, nil
}

// SelectModel picks the preferred model ID from a ranked list. Returns ""
// if the list is empty.
func SelectModel(ranked []ScoredModel) string {
	if len(ranked) == 0 {
		return ""
	}
	return ranked[0].ID
}

// getAndDecode performs a GET request with optional Bearer auth and extra
// headers, decodes the JSON response into out, and returns any error.
func getAndDecode(ctx context.Context, timeout time.Duration, endpoint, apiKey string, headers map[string]string, out any) error {
	reqCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/json")
	if apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+apiKey)
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

// MatchModelIDs returns every catalog entry whose normalized form contains
// the normalized request as a substring. Normalization lowercases, strips a
// single leading vendor namespace, and removes all non-alphanumeric
// separators, so "qwen/qwen3.6" and "Qwen3.6" and "qwen3.6" all match
// "Qwen3.6-35B-A3B-4bit" and "Qwen3.6-35B-A3B-nvfp4".
//
// The returned slice preserves original catalog case and order. An empty slice
// means no match; callers are responsible for deciding whether to pass the
// original request through to the provider unchanged or to escalate.
//
// This is the primary matching primitive since v0.9.2 — it replaces the
// scalar logic previously in NormalizeModelID. NormalizeModelID is retained
// as a backward-compatible wrapper.
func MatchModelIDs(requested string, catalog []string) []string {
	return modelmatch.Match(requested, catalog)
}

// NormalizeModelID resolves a caller-supplied model name against the server's
// canonical model catalog (the IDs returned by GET /v1/models).
//
// Prefer MatchModelIDs for new code; this wrapper is retained for backward
// compatibility with the v0.9.1 call signature. Behaviour:
//   - 0 matches → returns the original requested string, no error
//   - 1 match   → returns the catalog entry, no error
//   - 2+ matches → returns "" and an ambiguity error listing the candidates
func NormalizeModelID(requested string, catalog []string) (string, error) {
	if strings.TrimSpace(requested) == "" {
		return requested, nil
	}
	matches := MatchModelIDs(requested, catalog)
	switch len(matches) {
	case 0:
		return requested, nil
	case 1:
		return matches[0], nil
	default:
		return "", fmt.Errorf("ambiguous model %q: matches %v", requested, matches)
	}
}

---PROTOCOL---
package openai

// Protocol-level capability flags describe what the concrete provider can
// honor on the OpenAI-compatible wire: tool calls, streaming, and structured
// output modes. They are distinct from routing-layer capability (a
// benchmark-quality score used by smart routing). Callers use these flags to
// gate dispatch before sending unsupported request shapes.

// ProtocolCapabilities declares provider-owned protocol capability claims.
type ProtocolCapabilities struct {
	Tools            bool
	Stream           bool
	StructuredOutput bool
	// Thinking reports whether the provider accepts non-standard body fields
	// (openai-go WithJSONSet) used to control model-side reasoning.
	Thinking       bool
	ThinkingFormat ThinkingWireFormat
	// StrictThinkingModelMatch, when true, makes the openai layer return an
	// error if the request carries an explicit reasoning policy while the
	// model does not match the provider's wire format family (e.g. a Qwen
	// wire format with a non-Qwen model). Set true for providers that only
	// serve a single model family (OMLX → Qwen MLX). Providers that host
	// mixed model families (LM Studio can load Qwen, Gemma, Llama, etc.)
	// should leave this false so reasoning controls silently no-op on
	// non-matching models instead of failing the request.
	StrictThinkingModelMatch bool
	// ImplicitGenerationConfig declares that the inference server applies
	// the model's HuggingFace `generation_config.json` automatically when
	// the request omits sampler fields. vLLM does this by default; most
	// other local servers (omlx, lmstudio, lucebox) ship custom presets and
	// either ignore upstream defaults or replace them at repackage time
	// (MLX / GGUF strip generation_config.json), which is why ADR-007's
	// catalog sampling_profiles exist. Routing and the catalog-stale
	// nudge use this flag to distinguish "server has a sane default" from
	// "server will decode greedy" when no catalog profile is supplied.
	ImplicitGenerationConfig bool
}

type ThinkingWireFormat string

const (
	// ThinkingWireFormatThinkingMap sends `thinking: {type, budget_tokens}`.
	ThinkingWireFormatThinkingMap ThinkingWireFormat = "thinking_map"
	// ThinkingWireFormatQwen sends Qwen-family controls:
	// `enable_thinking` and `thinking_budget`.
	ThinkingWireFormatQwen ThinkingWireFormat = "qwen"
	// ThinkingWireFormatOpenRouter sends OpenRouter's nested `reasoning`
	// object with `effort`, `max_tokens`, or `exclude`.
	ThinkingWireFormatOpenRouter ThinkingWireFormat = "openrouter"
)

var (
	OpenAIProtocolCapabilities  = ProtocolCapabilities{Tools: true, Stream: true, StructuredOutput: true, Thinking: false}
	UnknownProtocolCapabilities ProtocolCapabilities
)

func (p *Provider) protocolCapabilities() ProtocolCapabilities {
	if p.capabilities != nil {
		return *p.capabilities
	}
	return OpenAIProtocolCapabilities
}

// SupportsTools reports whether the concrete provider accepts a `tools`
// field on `/v1/chat/completions` and returns structured `tool_calls` in the
// response.
func (p *Provider) SupportsTools() bool {
	return p.protocolCapabilities().Tools
}

// SupportsStream reports whether `stream: true` returns a well-formed SSE
// stream with incremental `choices[0].delta` chunks.
func (p *Provider) SupportsStream() bool {
	return p.protocolCapabilities().Stream
}

// SupportsStructuredOutput reports whether the provider honors
// `response_format: json_object` / tool-use-required semantics to produce a
// structured (JSON-shaped) response.
func (p *Provider) SupportsStructuredOutput() bool {
	return p.protocolCapabilities().StructuredOutput
}

// SupportsThinking reports whether the provider accepts non-standard request
// body fields used to cap or disable model-side reasoning. Providers returning
// false MUST have those fields stripped at serialization time.
func (p *Provider) SupportsThinking() bool {
	return p.protocolCapabilities().Thinking
}

func (p *Provider) thinkingWireFormat() ThinkingWireFormat {
	caps := p.protocolCapabilities()
	if !caps.Thinking {
		return ""
	}
	if caps.ThinkingFormat != "" {
		return caps.ThinkingFormat
	}
	return ThinkingWireFormatThinkingMap
}

func (p *Provider) strictThinkingModelMatch() bool {
	return p.protocolCapabilities().StrictThinkingModelMatch
}

// ImplicitGenerationConfig reports whether the provider's server applies a
// model-card-derived sampler bundle (`generation_config.json`) when the
// request omits sampler fields. Used by the agent CLI to tone the
// catalog-stale nudge per ADR-007 §7.
func (p *Provider) ImplicitGenerationConfig() bool {
	return p.protocolCapabilities().ImplicitGenerationConfig
}

// Package anthropic implements a agent.Provider for the Anthropic Claude API.
package anthropic

import (
