func OpenProgressLog(sessionLogDir, sessionID, prefix string) (*os.File, error) {
	if sessionLogDir == "" {
		return nil, nil
	}
	if sessionID == "" {
		sessionID = fmt.Sprintf("%s-%d", prefix, time.Now().UnixNano())
	}
	return sessionlog.OpenAppend(sessionLogDir, sessionID)
}

func MirrorEvents(dst chan<- Event, log io.Writer, ctx context.Context) (chan Event, <-chan struct{}) {
	mid := make(chan Event, cap(dst))
	done := make(chan struct{})
	go func() {
		defer close(done)
		for ev := range mid {
			WriteProgressEvent(log, ev)
			select {
			case dst <- ev:
			case <-ctx.Done():
				return
			}
		}
	}()
	return mid, done
}

func WriteProgressEvent(log io.Writer, ev Event) {
	if log == nil {
		return
	}
	if data, err := json.Marshal(ev); err == nil {
		_, _ = log.Write(data)
		_, _ = log.Write([]byte("\n"))
	}
}
package harnesses

import "github.com/DocumentDrivenDX/fizeau/internal/reasoning"

// AdapterReasoningValue resolves the public reasoning scalar into the value
// subprocess harnesses should pass to their native CLI flag. Empty, auto, off,
// and numeric 0 intentionally emit no flag.
func AdapterReasoningValue(req ExecuteRequest) string {
	value := req.Reasoning
	policy, err := reasoning.ParseString(value)
	if err != nil {
		return value
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return ""
	case reasoning.KindTokens:
		if policy.Tokens == 0 {
			return ""
		}
		return string(policy.Value)
	case reasoning.KindNamed:
		return string(policy.Value)
	default:
		return value
	}
}
